"""Configs generated by ``init`` from the installed plugins load once filled in."""

import asyncio
import tempfile
from pathlib import Path
from typing import Any
from unittest import IsolatedAsyncioTestCase, TestCase

import yaml
from wcpan.drive.client.config import create_config_scaffold as client_scaffold
from wcpan.drive.client.config._cfg import (
    _parse_main,  # pyright: ignore[reportPrivateUsage]
)
from wcpan.drive.server.app import entered_backends, managed_core, managed_off_main
from wcpan.drive.server.config import parse_config
from wcpan.drive.server.scaffold import create_config_scaffold as server_scaffold
from wcpan.drive.server.workers import noop_after_write


def _fill(section: dict[str, Any], **values: Any) -> None:
    for key, value in section.items():
        if value is None:
            section[key] = values[key]


class TestServerScaffold(IsolatedAsyncioTestCase):
    async def test_every_backend_enters_offline(self) -> None:
        # given
        raw = yaml.safe_load(server_scaffold(["synology", "filesystem"]))
        with tempfile.TemporaryDirectory() as tmp:
            _fill(raw["server"], database_url=str(Path(tmp) / "mirror.db"))
            _fill(
                raw["backends"]["synology"],
                url="https://nas.example",
                username="user",
                password="secret",
                webhook_callback_url="https://public.example",
            )
            raw["mounts"]["synology"]["source"] = "/volume1/photos"
            raw["mounts"]["filesystem"]["source"] = tmp
            config = parse_config(raw)
            # when
            async with (
                managed_off_main() as off_main,
                managed_core(
                    config, off_main=off_main, after_write=noop_after_write
                ) as core,
                entered_backends(config, core, offline=True) as backends,
            ):
                # then
                self.assertEqual(set(backends), {"synology", "filesystem"})
            await asyncio.sleep(0)


class TestClientScaffold(TestCase):
    def test_installed_plugins_make_a_valid_source(self) -> None:
        # given
        raw = yaml.safe_load(
            client_scaffold(["wcpan.drive.client.google", "crypt", "sqlite"])
        )
        # when
        (source,) = _parse_main(raw)
        # then
        self.assertEqual(source.name, "google")
        self.assertEqual(
            [_.name for _ in source.backend],
            [
                "wcpan.drive.client.google.create_backend",
                "wcpan.drive.client.crypt.create_middleware",
            ],
        )
        self.assertEqual(
            source.backend[0].kwargs, {"client_secret": None, "oauth_token": None}
        )
        self.assertEqual(source.cache[0].kwargs, {"dsn": None})
